head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "options.status(선택) 파라미터를 true 로 설정하면, options.type 속성값이 'browserPopup' 일때 상태바를 출력합니다.",
        "options.status(선택) 파라미터를 false 로 설정하면, options.type 속성값이 'browserPopup' 일때 상태바를 출력하지 않습니다.",
        "options.status(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
        "options.menubar(선택) 파라미터를 true 로 설정하면, options.type 속성값이 'browserPopup' 일때 상단 메뉴바를 출력합니다.",
        "options.menubar(선택) 파라미터를 false 로 설정하면, options.type 속성값이 'browserPopup' 일때 상단 메뉴바를 출력하지 않습니다.",
        "options.menubar(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
        "options.scrollbars(선택) 파라미터를 true 로 설정하면, options.type 속성값이 'browserPopup' 일때 스크롤바를 출력합니다.",
        "options.scrollbars(선택) 파라미터를 false 로 설정하면, options.type 속성값이 'browserPopup' 일때 스크롤바를 출력하지 않습니다.",
        "options.scrollbars(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
        "options.title(선택) 파라미터를 true 로 설정하면, options.type 속성값이 'browserPopup' 일때 제목 표시줄를 출력합니다.",
        "options.title(선택) 파라미터를 false 로 설정하면, options.type 속성값이 'browserPopup' 일때 제목 표시줄를 출력하지 않습니다.",
        "options.title(선택) 파라미터 생략 시, 기본값 'false' 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    $c.gcm.createLabel('label="[전제] options.type 은 browserPopup 고정입니다.\n[참고] Chrome·Edge 등 최신 브라우저는 window.open 의 status, menubar, scrollbars, title 창 옵션을 무시할 수 있으므로 열린 창의 막대 표시를 직접 확인합니다."', '', 'label1');

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 판정용 관찰 래퍼: 엔진이 window.open 에 넘긴 창 옵션 문자열을 기록 (동작은 원본 그대로 위임)
    let orgOpen = window.open;
    scwin.lastFeatures = "";
    window.open = function (url, name, features) {
        scwin.lastFeatures = features || "";
        return orgOpen.apply(this, arguments);
    };
};



scwin.popupUrl = "/sample/common_link/p_openPopup_popup.xml";



scwin.out = function (str) {
    wf_body_bottom.getObj("scwin").setReturnValue(str);
};



// 이전 테스트 팝업 정리 (내부 팝업을 정리했으면 true 반환)
scwin.closeAllPopup = function () {
    let list = $p.getAllPopupList().slice();
    let closedInner = false;
    for (let i = 0; i < list.length; i++) {
        let pw = list[i].popupWin;
        try {
            if (pw && typeof pw.forceClose === "function") {
                pw.forceClose();
                closedInner = true;
            } else if (pw && typeof pw.close === "function") {
                pw.close();
            }
        } catch (e) {}
    }
    return closedInner;
};



// 이전 팝업 정리 후 openPopup 실행
// (내부 팝업 정리는 비동기로 끝나므로 300ms 후 연다. 클릭 직후 5초 이내라 browserPopup 도 사용자 동작으로 처리됨)
scwin.runOpenPopup = function (optionList, callback, delay) {
    let fn = function () {
        for (let i = 0; i < optionList.length; i++) {
            $p.openPopup(scwin.popupUrl, optionList[i]);
        }
        if (callback) setTimeout(callback, delay || 1500);
    };
    if (scwin.closeAllPopup()) {
        setTimeout(fn, 300);
    } else {
        fn();
    }
};



// options.id 로 팝업 정보 조회 (Page Scope 적용 시 실행 ID 는 'mf_' 접두사가 붙음)
scwin.findPopup = function (id) {
    let list = $p.getAllPopupList();
    for (let i = list.length - 1; i >= 0; i--) {
        if ((list[i].options.org_id === id || list[i].options.id === id) && list[i].popupWin) return list[i];
    }
    return null;
};



// options.id 로 팝업 최상위 div 조회
scwin.popupEl = function (id) {
    return document.querySelector(".w2popup_window[id$='" + id + "']");
};



// 팝업 내부 요소(타이틀바 버튼 등) 조회
scwin.popupPart = function (id, suffix) {
    let el = scwin.popupEl(id);
    return el ? document.getElementById(el.id + "_" + suffix) : null;
};



scwin.rectStr = function (el) {
    let r = el.getBoundingClientRect();
    return "left " + Math.round(r.left + window.scrollX) + ", top " + Math.round(r.top + window.scrollY) + " / 크기 : " + Math.round(r.width) + " x " + Math.round(r.height);
};

scwin.btn_openPopup_onclick = function () {
    let status = par_status.getValue();
    let menubar = par_menubar.getValue();
    let scrollbars = par_scrollbars.getValue();
    let title = par_title.getValue();

    let options = { id: "popup_1", type: "browserPopup", left: "100px", top: "100px", width: "500px", height: "300px", popupName: "openPopup 팝업" };
    if (status !== "") options.status = (status === "true");
    if (menubar !== "") options.menubar = (menubar === "true");
    if (scrollbars !== "") options.scrollbars = (scrollbars === "true");
    if (title !== "") options.title = title;   // String 타입("true"/"false")

    scwin.runOpenPopup([options], scwin.printResult, 2000);
};



// validation 1~12 판정 출력 (window.open 창 옵션 중 status/menubar/scrollbars/title · 새 창 document.title · 팝업 창의 막대 표시 상태)
scwin.printResult = function (tries) {
    let pw = scwin.findPopup("popup_1");
    if (!pw) {
        scwin.out("window.open 결과 : 차단됨");
        return;
    }
    let w = pw.popupWin;
    let feat = scwin.lastFeatures.split(",").filter(function (f) {
        return /^(status|menubar|scrollbars|title)=/.test(f.trim());
    }).join(",");
    // 새 창 로드(document.title 설정)가 끝날 때까지 최대 5초 대기 후 출력
    let title = "";
    try { title = w.document.readyState === "complete" ? w.document.title : ""; } catch (e) {}
    tries = tries || 0;
    if (title === "" && tries < 25) {
        setTimeout(function () { scwin.printResult(tries + 1); }, 200);
        return;
    }
    scwin.out("창 옵션 : " + feat + " / document.title : " + title + " / statusbar : " + w.statusbar.visible + " / menubar : " + w.menubar.visible + " / scrollbars : " + w.scrollbars.visible + " / toolbar(제목 표시줄) : " + w.toolbar.visible);
};
